       &lt;meta charset="utf-8"&gt;
       &lt;script src="wasm_exec.js"&gt;&lt;/script&gt;
       &lt;script&gt;
           (async function loadAndRunGoWasm() {
               const go = new Go();
               const response = await fetch("main.wasm");
               const buffer = await response.arrayBuffer();
               const result = await WebAssembly.instantiate(buffer, go.importObject);
               go.run(result.instance);
               const img = window.decodePsd();
               const el = document.getElementById("img");
               el.src = "data:image/png;base64," + img;
         })();
       &lt;/script&gt;
    &lt;/head&gt;
    &lt;body&gt;
        &lt;img id="img"&gt;
    &lt;/body&gt;
&lt;/html&gt;```

```package main

import (
	"bytes"
	_ "embed"
	"encoding/base64"
	"image"
	"image/png"
	"syscall/js"

	_ "<http://github.com/oov/psd|github.com/oov/psd>"
)

//go:embed assets/image.psd
var psd []byte

func main() {
	c := make(chan struct{}, 0)
	js.Global().Set("decodePsd", js.FuncOf(decodePsd))
	&lt;-c
}

func decodePsd(this js.Value, args []js.Value) interface{} {
	img, _, err := image.Decode(bytes.NewReader(psd))
	if err != nil {
		panic(err)
	}
	out := new(bytes.Buffer)
	err = png.Encode(out, img)
	if err != nil {
		panic(err)
	}
	enc := base64.StdEncoding.EncodeToString(out.Bytes())
	return js.ValueOf(enc)
}```
